// SA Check - Company Lookup (auto-registers new servers) + central alert rules
// Author: Eng. Samir Abou El Khair

// ---- 1) Custom names (optional): one per line, "IP = name" ----
// Any server NOT listed here is registered automatically with the hostname
// it reports, so you only list servers whose name you want to override.
const table = `
203.0.113.10 = server.example-company-a.com
203.0.113.11 = server.example-company-b.com
`;

// ---- 2) Alert rules ----
const ignoredServices = ["php-fpm"];          // never alert, on any server
const perServerIgnoredServices = {};          // { "IP": ["service"] }
const DEDUP = true;                           // false = alert on every run
const REMINDER_MS = 60 * 60 * 1000;           // reminder while still broken

const staticData = $getWorkflowStaticData('global');
staticData.servers = staticData.servers || {};
staticData.lastAlerts = staticData.lastAlerts || {};

const custom = {};
for (const line of table.split("\n")) {
  const i = line.indexOf("=");
  if (i > 0) custom[line.slice(0, i).trim()] = line.slice(i + 1).trim();
}

const input = $input.first().json;
const data = input.body || input;
const ip = data.ip;
const nowIso = new Date().toISOString();

// Name priority: custom table > already registered > reported hostname.
const reg = staticData.servers[ip];
let company = custom[ip];
if (!company) {
  if (reg && !reg.name.startsWith("Unnamed")) {
    company = reg.name;
  } else {
    company = data.hostname || (reg && reg.name) || ("Unnamed (" + ip + ")");
  }
}
staticData.servers[ip] = {
  name: company,
  firstSeen: reg ? reg.firstSeen : nowIso,
  lastSeen: nowIso,
};

// Status is decided here, centrally.
const ignored = [...ignoredServices, ...(perServerIgnoredServices[ip] || [])];
let status = "ok";
for (const [service, state] of Object.entries(data.services || {})) {
  if (state === "stopped" && !ignored.includes(service)) {
    status = "critical";
    break;
  }
}
if (status === "ok") {
  const disk = data.resources?.disk_usage_percent ?? 0;
  const ram = data.resources?.ram_usage_percent ?? 0;
  if (disk >= 90 || ram >= 90) status = "warning";
}

// De-duplication: alert on status change, then hourly while still broken.
if (status === "ok") {
  delete staticData.lastAlerts[ip];           // recovered: next problem alerts at once
} else if (DEDUP) {
  const last = staticData.lastAlerts[ip];
  const nowMs = Date.now();
  const send = !last || last.status !== status || nowMs - last.time >= REMINDER_MS;
  if (!send) return [];
  staticData.lastAlerts[ip] = { status, time: nowMs };
}

return [{ json: { ...data, company, status } }];

